const tabID = "tab_8d8a891e-b5d5-43ca-aa87-6800a28a5dce";
const script = `
(() => {
  const out = {};

  // 1. Theme toggle
  const toggle = document.getElementById('theme-toggle');
  out.initialTheme = document.documentElement.getAttribute('data-theme');
  toggle.click();
  out.afterClickTheme = document.documentElement.getAttribute('data-theme');
  out.storedTheme = localStorage.getItem('pm-theme');
  out.ariaLabel = toggle.getAttribute('aria-label');
  out.labelText = toggle.querySelector('.theme-toggle__label').textContent;
  toggle.click();
  out.backToInitial = document.documentElement.getAttribute('data-theme');

  // 2. Mobile nav toggle
  const navToggle = document.getElementById('nav-toggle');
  const navMenu = document.getElementById('nav-menu');
  navToggle.click();
  out.menuOpen = navMenu.classList.contains('is-open');
  out.navExpanded = navToggle.getAttribute('aria-expanded');
  navToggle.click();
  out.menuClosed = !navMenu.classList.contains('is-open');

  // 3. Form validation
  const form = document.getElementById('contact-form');
  const status = document.getElementById('form-status');
  form.dispatchEvent(new Event('submit', {bubbles:true, cancelable:true}));
  out.emptySubmitStatus = status.textContent;
  out.emptySubmitIsError = status.classList.contains('is-error');

  form.elements.name.value = 'Jane';
  form.elements.email.value = 'not-an-email';
  form.elements.message.value = 'Hi';
  form.dispatchEvent(new Event('submit', {bubbles:true, cancelable:true}));
  out.badEmailStatus = status.textContent;

  form.elements.email.value = 'jane@example.com';
  form.dispatchEvent(new Event('submit', {bubbles:true, cancelable:true}));
  out.goodSubmitStatus = status.textContent;
  out.formReset = form.elements.name.value === '';

  // 4. Overflow check
  out.docScrollWidth = document.documentElement.scrollWidth;
  out.winInnerWidth = window.innerWidth;
  out.horizontalOverflow = document.documentElement.scrollWidth > window.innerWidth + 1;

  // 5. Footer year
  out.footerYear = document.getElementById('year').textContent;

  // 6. Nav anchors resolve to real sections
  out.brokenAnchors = [...document.querySelectorAll('a[href^="#"]')]
    .map(a => a.getAttribute('href'))
    .filter(h => h.length > 1 && !document.querySelector(h));

  return out;
})()
`;
const r = await tools.browser.evaluate({ tabID, script });
return r.value;

