const tabID = "tab_8d8a891e-b5d5-43ca-aa87-6800a28a5dce";
const script = `
(() => {
  const out = {};
  // Theme: dark persisted -> toggle to light -> persists
  out.themeOnLoad = document.documentElement.getAttribute('data-theme');
  const t = document.getElementById('theme-toggle');
  t.click();
  out.afterToggle = document.documentElement.getAttribute('data-theme');
  out.stored = localStorage.getItem('pm-theme');
  out.label = t.querySelector('.theme-toggle__label').textContent;
  t.click();
  out.roundTrip = document.documentElement.getAttribute('data-theme');

  // Nav drawer
  const nt = document.getElementById('nav-toggle'), nm = document.getElementById('nav-menu');
  nt.click(); out.drawerOpen = nm.classList.contains('is-open') && nt.getAttribute('aria-expanded')==='true';
  document.dispatchEvent(new KeyboardEvent('keydown', {key:'Escape'}));
  out.drawerEscapeCloses = !nm.classList.contains('is-open');

  // Form
  const f = document.getElementById('contact-form'), st = document.getElementById('form-status');
  f.dispatchEvent(new Event('submit',{bubbles:true,cancelable:true}));
  out.emptyErr = st.classList.contains('is-error');
  f.elements.name.value='Jane'; f.elements.email.value='jane@ex.com'; f.elements.message.value='Hello';
  f.dispatchEvent(new Event('submit',{bubbles:true,cancelable:true}));
  out.success = !st.classList.contains('is-error') && f.elements.name.value==='';

  // Structure
  out.sections = [...document.querySelectorAll('main section[id]')].map(s=>s.id);
  out.navAnchors = [...document.querySelectorAll('.navbar__link')].map(a=>a.getAttribute('href'));
  out.brokenAnchors = [...document.querySelectorAll('a[href^="#"]')].map(a=>a.getAttribute('href')).filter(h=>h.length>1 && !document.querySelector(h));
  out.noHorizontalScroll = document.documentElement.scrollWidth <= window.innerWidth + 1;
  out.footerYear = document.getElementById('year').textContent;
  out.styleLinked = !!document.querySelector('link[href="style.css"]');
  out.scriptLinked = !!document.querySelector('script[src="script.js"]');
  return out;
})()
`;
const r = await tools.browser.evaluate({ tabID, script });
const logs = await tools.browser.console({ tabID, level: "error", limit: 100 });
return { behavior: r.value, consoleErrors: logs.messages.map(m=>m.text) };

