const tabID = "tab_260721d4-43fd-411e-98c6-94328927776d";
// disable transitions for accurate measurement
await tools.browser.evaluate({ tabID, script: `
(() => { let s=document.getElementById('no-anim');
  if(!s){s=document.createElement('style');s.id='no-anim';document.head.appendChild(s);}
  s.textContent='*,*::before,*::after{transition:none !important;animation:none !important}'; return 'ok'; })()` });

const checker = `
(() => {
  const parse = c => { const m = c.match(/rgba?\\(([^)]+)\\)/); if (!m) return null;
    const p = m[1].split(',').map(s => parseFloat(s.trim()));
    return { r: p[0], g: p[1], b: p[2], a: p.length > 3 ? p[3] : 1 }; };
  const lum = ({r,g,b}) => { const f = v => { v/=255; return v <= 0.03928 ? v/12.92 : Math.pow((v+0.055)/1.055, 2.4); };
    return 0.2126*f(r) + 0.7152*f(g) + 0.0722*f(b); };
  const blend = (fg,bg) => ({ r: fg.r*fg.a+bg.r*(1-fg.a), g: fg.g*fg.a+bg.g*(1-fg.a), b: fg.b*fg.a+bg.b*(1-fg.a), a:1 });
  const effBg = el => { let n = el;
    while (n && n !== document.documentElement) { const c = parse(getComputedStyle(n).backgroundColor);
      if (c && c.a > 0.95) return c; n = n.parentElement; }
    return {r:255,g:255,b:255,a:1}; };
  const bad = [];
  document.querySelectorAll('*').forEach(el => {
    if (!el.offsetParent && getComputedStyle(el).position !== 'fixed') return;
    if (![...el.childNodes].some(n => n.nodeType===3 && n.textContent.trim())) return;
    const cs = getComputedStyle(el);
    const fg = parse(cs.color), bg = effBg(el);
    const eff = fg.a < 1 ? blend(fg,bg) : fg;
    const L1 = Math.max(lum(eff),lum(bg)), L2 = Math.min(lum(eff),lum(bg));
    const ratio = (L1+0.05)/(L2+0.05);
    const px = parseFloat(cs.fontSize), bold = parseInt(cs.fontWeight,10) >= 700;
    const need = (px >= 24 || (px >= 18.66 && bold)) ? 3 : 4.5;
    if (ratio < need) bad.push({ sel: el.tagName.toLowerCase()+(typeof el.className==='string'&&el.className?'.'+el.className.trim().split(/\\s+/).join('.'):''), ratio:+ratio.toFixed(2), need });
  });
  return { theme: document.documentElement.getAttribute('data-theme'), count: bad.length, bad };
})()
`;

