/* --- Board --- */
.game__board {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: var(--space-3);
}

/* --- Card --- */
.card {
  position: relative;
  aspect-ratio: 1;
  padding: 0;
  background: none;
  border: 0;
  border-radius: var(--radius-md);
  cursor: pointer;
  perspective: 700px;
  -webkit-tap-highlight-color: transparent;
}

.card:focus-visible {
  outline: 3px solid var(--color-focus);
  outline-offset: 3px;
}

.card__inner {
  position: absolute;
  inset: 0;
  transform-style: preserve-3d;
  transition: transform 380ms cubic-bezier(0.4, 0.2, 0.2, 1);
}

.card.is-flipped .card__inner,
.card.is-matched .card__inner {
  transform: rotateY(180deg);
}

.card__face {
  position: absolute;
  inset: 0;
  display: grid;
  place-items: center;
  overflow: hidden;
  backface-visibility: hidden;
  -webkit-backface-visibility: hidden;
  border-radius: var(--radius-md);
  border: 1px solid var(--color-border);
}

.card__face--back {
  background:
    repeating-linear-gradient(
      45deg,
      var(--color-accent-soft) 0 8px,
      transparent 8px 16px
    ),
    var(--color-surface);
  color: var(--color-accent);
  font-size: 1.35rem;
  font-weight: 800;
  letter-spacing: 0.05em;
}

.card__face--front {
  background-color: #0d0d0d;
  transform: rotateY(180deg);
}

.card__img {
  width: 100%;
  height: 100%;
  display: block;
  object-fit: cover;
}

/* --- Matched state --- */
.card.is-matched {
  cursor: default;
}

.card.is-matched .card__inner {
  transform: rotateY(180deg) scale(1);
}

.card.is-matched .card__face--front {
  border-color: var(--color-success);
  box-shadow: 0 0 0 2px var(--color-success);
  animation: card-pop 320ms ease;
}

.card.is-wrong .card__face--front {
  animation: card-shake 320ms ease;
}

@keyframes card-pop {
  0% { transform: rotateY(180deg) scale(1); }
  50% { transform: rotateY(180deg) scale(1.08); }
  100% { transform: rotateY(180deg) scale(1); }
}

@keyframes card-shake {
  0%, 100% { transform: rotateY(180deg) translateX(0); }
  25% { transform: rotateY(180deg) translateX(-4px); }
  75% { transform: rotateY(180deg) translateX(4px); }
}

/* --- Controls & status --- */
.game__controls {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: center;
  gap: var(--space-4);
  text-align: center;
}

.game__status {
  flex: 1 1 100%;
  min-height: 1.5rem;
  margin: 0;
  font-size: var(--fs-sm);
  font-weight: 600;
  color: var(--color-text-muted);
}

.game__status.is-win {
  color: var(--color-success);
}

/* =========================================================
   Contact
   ========================================================= */

