/* ---------------------------------------------------------
   Product — 4x4 memory matching game
   --------------------------------------------------------- */
var board = document.getElementById("game-board");
var movesEl = document.getElementById("game-moves");
var matchesEl = document.getElementById("game-matches");
var timeEl = document.getElementById("game-time");
var statusEl = document.getElementById("game-status");
var restartBtn = document.getElementById("game-restart");

if (board && movesEl && matchesEl && timeEl && statusEl && restartBtn) {
  // 8 unique gems, each used twice = 16 cards on a 4x4 board.
  var GEMS = [
    { id: "purple-diamond", src: "assets/gem-purple-diamond.svg", name: "Purple diamond" },
    { id: "green-circle", src: "assets/gem-green-circle.svg", name: "Green circle" },
    { id: "orange-octagon", src: "assets/gem-orange-octagon.svg", name: "Orange octagon" },
    { id: "blue-hexagon", src: "assets/gem-blue-hexagon.svg", name: "Blue hexagon" },
    { id: "pink-pentagon", src: "assets/gem-pink-pentagon.svg", name: "Pink pentagon" },
    { id: "lavender", src: "assets/gem-lavender.svg", name: "Lavender gem" },
    { id: "magenta-star", src: "assets/gem-magenta-star.svg", name: "Magenta star" },
    { id: "green-diamond", src: "assets/gem-green-diamond.svg", name: "Green diamond" }
  ];

  var PAIR_COUNT = GEMS.length;
  var LOCK_MS = 900;

  var deck = [];        // 16 card data objects, shuffled
  var firstCard = null; // card currently face-up awaiting a pair
  var lockBoard = false;
  var moves = 0;
  var matches = 0;
  var seconds = 0;
  var timerId = null;
  var unflipId = null;
  var gameToken = 0;    // invalidates stale timeouts after a restart
  var started = false;

  /** Fisher-Yates shuffle — returns a new array. */
  function shuffle(items) {
    var arr = items.slice();
    for (var i = arr.length - 1; i > 0; i--) {
      var j = Math.floor(Math.random() * (i + 1));
      var tmp = arr[i];
      arr[i] = arr[j];
      arr[j] = tmp;
    }
    return arr;
  }

  function formatTime(total) {
    var m = Math.floor(total / 60);
    var s = total % 60;
    var mm = m < 10 ? "0" + m : String(m);
    var ss = s < 10 ? "0" + s : String(s);
    return mm + ":" + ss;
  }

  function updateStats() {
    movesEl.textContent = String(moves);
    matchesEl.textContent = matches + " / " + PAIR_COUNT;
    timeEl.textContent = formatTime(seconds);
  }

  function setStatus(message, isWin) {
    statusEl.textContent = message;
    statusEl.classList.toggle("is-win", Boolean(isWin));
  }

  function stopTimer() {
    if (timerId !== null) {
      window.clearInterval(timerId);
      timerId = null;
    }
  }

  function startTimer() {
    if (timerId !== null) return;
    timerId = window.setInterval(function () {
      seconds += 1;
      timeEl.textContent = formatTime(seconds);
    }, 1000);
  }

  /** Build a single card element. */
  function createCard(gem) {
    var btn = document.createElement("button");
    btn.type = "button";
    btn.className = "card";
    btn.dataset.gem = gem.id;
    btn.setAttribute("aria-label", "Face-down card");

    var inner = document.createElement("span");
    inner.className = "card__inner";

    var back = document.createElement("span");
    back.className = "card__face card__face--back";
    back.setAttribute("aria-hidden", "true");
    back.textContent = "?";

    var front = document.createElement("span");
    front.className = "card__face card__face--front";
    front.setAttribute("aria-hidden", "true");

    var img = document.createElement("img");
    img.className = "card__img";
    img.src = gem.src;
    img.alt = "";
    img.draggable = false;
    front.appendChild(img);

    inner.appendChild(back);
    inner.appendChild(front);
    btn.appendChild(inner);
    return btn;
  }

  /** Deal a fresh shuffled board into the DOM. */
  function buildBoard() {
    var pairs = [];
    GEMS.forEach(function (gem) {
      pairs.push(gem, gem);
    });
    deck = shuffle(pairs);

    // Clear any pending unflip from a previous round.
    if (unflipId !== null) {
      window.clearTimeout(unflipId);
      unflipId = null;
    }

    board.textContent = "";
    deck.forEach(function (gem) {
      board.appendChild(createCard(gem));
    });
  }

  function resetGame() {
    gameToken += 1;
    stopTimer();
    if (unflipId !== null) {
      window.clearTimeout(unflipId);
      unflipId = null;
    }

    firstCard = null;
    lockBoard = false;
    moves = 0;
    matches = 0;
    seconds = 0;
    started = false;

    buildBoard();
    updateStats();
    setStatus("Flip two cards to find a matching pair.", false);
  }

  function onMatch(card, gem) {
    card.classList.add("is-matched");
    card.classList.remove("is-flipped");
    card.setAttribute("aria-label", "Matched: " + gem.name);
    if (firstCard) {
      firstCard.classList.add("is-matched");
      firstCard.classList.remove("is-flipped");
      firstCard.setAttribute("aria-label", "Matched: " + gem.name);
      firstCard = null;
    }
    matches += 1;
    updateStats();

    if (matches === PAIR_COUNT) {
      stopTimer();
      setStatus(
        "You cleared the board in " +
          moves +
          " moves and " +
          formatTime(seconds) +
          ". 🎉",
        true
      );
    }
  }

  function onMismatch(a, b, token) {
    lockBoard = true;
    a.classList.add("is-wrong");
    b.classList.add("is-wrong");
    unflipId = window.setTimeout(function () {
      // A restart happened while we were waiting — bail out.
      if (token !== gameToken) return;
      [a, b].forEach(function (el) {
        el.classList.remove("is-flipped", "is-wrong");
        el.setAttribute("aria-label", "Face-down card");
      });
      firstCard = null;
      lockBoard = false;
      unflipId = null;
    }, LOCK_MS);
  }

  function handleFlip(card) {
    if (lockBoard) return;
    if (card.classList.contains("is-matched")) return;
    if (card === firstCard) return;

    if (!started) {
      started = true;
      startTimer();
    }

    card.classList.add("is-flipped");
    var gemId = card.dataset.gem;
    var gem = GEMS.filter(function (g) {
      return g.id === gemId;
    })[0];
    card.setAttribute("aria-label", gem ? gem.name : "Flipped card");

    if (!firstCard) {
      firstCard = card;
      return;
    }

    moves += 1;
    updateStats();

    var a = firstCard;
    var b = card;
    firstCard = null;

    if (a.dataset.gem === b.dataset.gem) {
      onMatch(b, gem);
    } else {
      onMismatch(a, b, gameToken);
    }
  }

  board.addEventListener("click", function (event) {
    var card = event.target.closest(".card");
    if (!card || !board.contains(card)) return;
    handleFlip(card);
  });

  restartBtn.addEventListener("click", function () {
    resetGame();
    board.querySelector(".card") && board.querySelector(".card").focus();
  });

  resetGame();
}

/* ---------------------------------------------------------
   Footer year
   --------------------------------------------------------- */

