  const mismatchB = byGem[gems[2]][0];

  // --- TEST 1: mismatch behaviour ---
  click(mismatchA);
  click(mismatchB);
  out.afterMismatch = {
    flippedCount: board.querySelectorAll('.is-flipped').length,
    wrongCount: board.querySelectorAll('.is-wrong').length,
    moves: document.getElementById('game-moves').textContent,
    locked: board.querySelectorAll('.is-matched').length
  };

  // wait for the 900ms unflip
  await new Promise(r => setTimeout(r, 1100));
  out.afterUnflip = {
    flippedCount: board.querySelectorAll('.is-flipped').length,
    wrongCount: board.querySelectorAll('.is-wrong').length,
    status: document.getElementById('game-status').textContent
  };

  // --- TEST 2: match behaviour ---
  click(pairA[0]);
  click(pairA[1]);
  out.afterMatch = {
    matchedCount: board.querySelectorAll('.is-matched').length,
    matches: document.getElementById('game-matches').textContent,
    moves: document.getElementById('game-moves').textContent,
    firstCardAria: pairA[0].getAttribute('aria-label')
  };

  // --- TEST 3: matched cards ignore further clicks ---
  click(pairA[0]);
  click(pairA[0]);
  out.matchedIgnoresClicks = {
    flippedCount: board.querySelectorAll('.is-flipped').length,
    matchedCount: board.querySelectorAll('.is-matched').length
  };

  // --- TEST 4: same card clicked twice counts once ---
  const solo = mismatchA;
  click(solo);
