  out.sameCardTwice = { flippedCount: board.querySelectorAll('.is-flipped').length };

  // reset flipped state on solo
  solo.classList.remove('is-flipped');

  return out;
})()
`;
const r = await tools.browser.evaluate({ tabID, script });
return r.value;

