  click(first);
  out.timerAfterFirstClick_started = $('game-time').textContent;
  // wait ~1.3s to see it tick
  await new Promise(r => setTimeout(r, 1300));
  out.timerAfterWait = $('game-time').textContent;

  // Solve the whole board
  const byGem = {};
  [...board.querySelectorAll('.card')].forEach(c => { (byGem[c.dataset.gem] ||= []).push(c); });
