  for (const gem of Object.keys(byGem)) {
    const pair = byGem[gem];
    if (pair[0].classList.contains('is-matched')) continue;
    click(pair[0]); click(pair[1]);
    totalClicks += 2;
    await new Promise(r => setTimeout(r, 30));
  }
  await new Promise(r => setTimeout(r, 1200));

  out.afterWin = {
    matched: board.querySelectorAll('.is-matched').length,
    matches: $('game-matches').textContent,
    moves: $('game-moves').textContent,
    status: $('game-status').textContent,
    statusIsWin: $('game-status').classList.contains('is-win')
  };

  // Timer should be stopped now. Wait to confirm it doesn't keep ticking.
  const frozenTime = $('game-time').textContent;
  await new Promise(r => setTimeout(r, 1300));
