  // Confirm the board grid template resolves to 4 columns
  const board = document.getElementById('game-board');
  const cs = getComputedStyle(board);
  out.boardGridTemplate = cs.gridTemplateColumns;
  out.boardDisplay = cs.display;
  out.match768 = window.matchMedia('(max-width: 768px)').matches;
  return out;
})()` });
