(() => {
  // 1. Extract every rule inside @media (max-width: 768px)
  const sheet = [...document.styleSheets].find(s => (s.href||'').includes('style.css'));
  let mobileCss = '';
  for (const rule of sheet.cssRules) {
    if (rule.media && rule.media.mediaText.includes('max-width: 768px')) {
      for (const r of rule.cssRules) mobileCss += r.cssText + '\n';
    }
  }

  // 2. Apply those rules unconditionally + pin the page to 360px wide
  let sim = document.getElementById('mobile-sim');
  if (!sim) { sim = document.createElement('style'); sim.id='mobile-sim'; document.head.appendChild(sim); }
  sim.textContent = mobileCss + '\nhtml,body{width:360px !important;overflow-x:visible !important}';

  const rect = el => { const r = el.getBoundingClientRect(); return {l:Math.round(r.left), t:Math.round(r.top), w:Math.round(r.width), h:Math.round(r.height), r:Math.round(r.right), b:Math.round(r.bottom)}; };

  const controls = document.querySelector('.game__controls');
  const status   = document.getElementById('game-status');
  const btn      = document.getElementById('game-restart');
  const game     = document.querySelector('.game');

  const cs = getComputedStyle(controls);
  const ss = getComputedStyle(status);

  return {
    viewport: window.innerWidth,
    bodyWidth: document.body.getBoundingClientRect().width,
    docScrollWidth: document.documentElement.scrollWidth,
    hasHOverflow: document.documentElement.scrollWidth > window.innerWidth + 1,
    controls: { ...rect(controls), display: cs.display, dir: cs.flexDirection, wrap: cs.flexWrap, alignItems: cs.alignItems, gap: cs.gap },
    status:   { ...rect(status), flex: ss.flex, width: ss.width, alignSelf: ss.alignSelf, textAlign: ss.textAlign },
    button:   rect(btn),
    game:     rect(game),
    statusOutsideControls: rect(status).r > rect(controls).r + 1 || rect(status).l < rect(controls).l - 1,
    statusBelowButton: rect(status).t >= rect(btn).b,
    overlapsButton: !(rect(status).b <= rect(btn).t || rect(status).t >= rect(btn).b || rect(status).r <= rect(btn).l || rect(status).l >= rect(btn).r)
  };
})()

