const tabs = await tools.browser.tabs.list();
let tab = tabs.tabs.find(t => t.url && t.url.includes("index.html"));
await tools.browser.reload({ tabID: tab.id });

const checks = `
(() => {
  // 1. All board images loaded?
  const imgs = [...document.querySelectorAll('#game-board img')];
  const imgState = imgs.map(i => ({ src: i.getAttribute('src'), ok: i.complete && i.naturalWidth > 0 }));

  // 2. Mobile sim: apply <=768px rules + pin body to 360px
  const sheet = [...document.styleSheets].find(s => (s.href||'').includes('style.css'));
  let mobileCss = '';
  for (const rule of sheet.cssRules) {
    if (rule.media && rule.media.mediaText.includes('max-width: 768px')) {
      for (const r of rule.cssRules) mobileCss += r.cssText + '\\n';
    }
  }
  let sim = document.getElementById('mobile-sim');
  if (!sim) { sim = document.createElement('style'); sim.id='mobile-sim'; document.head.appendChild(sim); }
  sim.textContent = mobileCss + '\\nhtml,body{width:360px !important}';

  const rect = el => { const r = el.getBoundingClientRect(); return {l:Math.round(r.left),t:Math.round(r.top),w:Math.round(r.width),r:Math.round(r.right),b:Math.round(r.bottom)}; };
  const c = rect(document.querySelector('.game__controls'));
  const s = rect(document.getElementById('game-status'));
  const b = rect(document.getElementById('game-restart'));

  // any non-fixed element wider than 360?
  const wide = [];
  for (const el of document.querySelectorAll('body *')) {
    if (getComputedStyle(el).position === 'fixed') continue;
    const r = el.getBoundingClientRect();
    if (r.right > 361 && r.width > 0) wide.push((el.className||el.tagName).toString().slice(0,40) + ' r=' + Math.round(r.right));
  }

  sim.remove();
  return {
    boardImages: imgState,
    allImagesOK: imgState.length === 16 && imgState.every(i => i.ok),
    mobile: {
      controls: c, status: s, button: b,
      statusBelowButton: s.t >= b.b - 1,
      statusInsideControls: s.l >= c.l-1 && s.r <= c.r+1,
      overflowingElements: wide
    }
  };
})()
`;
const r = await tools.browser.evaluate({ tabID: tab.id, script: checks });

const msgs = await tools.browser.console.list({ tabID: tab.id });
const errors = msgs.messages.filter(m => m.level === "error" || m.level === "warning");

return { page: r.value, consoleIssues: errors.map(m => m.level + ": " + m.text.slice(0,160)) };

