// Flip a matching pair so the gem faces are visible
const flipped = `
(() => {
  const cards = [...document.querySelectorAll('#game-board .card')];
  const bySrc = {};
  let first = null, second = null;
  for (const c of cards) {
    const img = c.querySelector('img');
    if (!img) continue;
    const s = img.getAttribute('src');
    if (bySrc[s] === undefined) { bySrc[s] = c; }
    else { first = bySrc[s]; second = c; break; }
  }
  if (!first) return { err: 'no pair found', cards: cards.length };
  first.click();
  second.click();
  return { clicked: first.querySelector('img').getAttribute('src'),
           flippedCount: cards.filter(c => c.classList.contains('is-flipped')).length };
})()
`;
