119: }
120: 
121: ul {
122:   margin: 0;
123:   padding: 0;
124:   list-style: none;
125: }
126: 
127: a {
128:   color: var(--color-accent);
129:   text-decoration: none;
130:   transition: color var(--transition);
131: }
132: 
133: a:hover {
134:   color: var(--color-accent-strong);
135: }
136: 
137: :focus-visible {
138:   outline: 3px solid var(--color-focus);
139:   outline-offset: 3px;
140:   border-radius: var(--radius-sm);
141: }
142: 
143: /* ---------- Layout helpers ---------- */
144: .container {
145:   width: 100%;
146:   max-width: var(--container-max);
147:   margin-inline: auto;
148:   padding-inline: var(--space-5);
149: }
150: 
151: .section {
152:   padding-block: var(--space-8);
153: }
154: 
155: .section--muted {
156:   background-color: var(--color-surface-alt);
157:   border-block: 1px solid var(--color-border);
158: }
159: 
160: .section__header {
161:   max-width: 42rem;
162:   margin-bottom: var(--space-7);
163: }
164: 
165: .section__eyebrow {
166:   margin-bottom: var(--space-2);
167:   font-size: var(--fs-sm);
168:   font-weight: 700;
169:   letter-spacing: 0.14em;
170:   text-transform: uppercase;
171:   color: var(--color-accent);
172: }
173: 
174: .section__title {
175:   font-size: var(--fs-xl);
176:   margin-bottom: var(--space-3);
177: }
178: 
179: .section__lead {
180:   color: var(--color-text-muted);
181:   font-size: var(--fs-md);
182: }
183: 
184: /* ---------- Buttons ---------- */
185: .btn {
186:   display: inline-flex;
187:   align-items: center;
188:   justify-content: center;
189:   gap: var(--space-2);
190:   padding: 0.75rem 1.5rem;
191:   border: 1px solid transparent;
192:   border-radius: 999px;
193:   font: inherit;
194:   font-weight: 600;
195:   line-height: 1;
196:   cursor: pointer;
197:   transition: background-color var(--transition), color var(--transition),
198:     border-color var(--transition), transform var(--transition);
199: }
200: 
201: .btn:active {
202:   transform: translateY(1px);
203: }
204: 
205: .btn--primary {
206:   background-color: var(--color-accent);
207:   color: var(--color-on-accent);
208: }
209: 
210: .btn--primary:hover {
211:   background-color: var(--color-accent-strong);
212:   color: var(--color-on-accent);
213: }
214: 
215: .btn--ghost {
216:   background-color: transparent;
217:   color: var(--color-text);
218:   border-color: var(--color-border);
219: }
220: 
221: .btn--ghost:hover {
222:   border-color: var(--color-accent);
223:   color: var(--color-accent);
224: }
225: 
226: .btn--block {
227:   width: 100%;
228: }
229: 
230: /* =========================================================
231:    Navbar — fixed
232:    ========================================================= */
233: .site-header {
234:   position: fixed;
235:   inset: 0 0 auto 0;
236:   z-index: 100;
237:   background-color: color-mix(in srgb, var(--color-bg) 88%, transparent);
238:   backdrop-filter: blur(10px);
239:   -webkit-backdrop-filter: blur(10px);
240:   border-bottom: 1px solid var(--color-border);
241: }
242: 
243: .navbar {
244:   max-width: var(--container-max);
245:   margin-inline: auto;
246:   padding: var(--space-3) var(--space-5);
247:   min-height: var(--navbar-height);
248:   display: flex;
249:   align-items: center;
250:   justify-content: space-between;
251:   gap: var(--space-4);
252: }
253: 
254: .navbar__brand {
255:   display: inline-flex;
256:   align-items: center;
257:   gap: var(--space-3);
258:   color: var(--color-text);
259:   font-weight: 700;
260: }
261: 
262: .navbar__brand:hover {
263:   color: var(--color-accent);
264: }
265: 
266: .navbar__initials {
267:   display: grid;
268:   place-items: center;
269:   width: 2.25rem;
270:   height: 2.25rem;
271:   border-radius: 50%;
272:   background-color: var(--color-accent);
273:   color: var(--color-on-accent);
274:   font-size: var(--fs-sm);
275:   letter-spacing: 0.02em;
276: }
277: 
278: .navbar__name {
279:   font-size: var(--fs-md);
280: }
281: 
282: .navbar__menu {
283:   display: flex;
284:   align-items: center;
285:   gap: var(--space-5);
286: }
287: 
288: .navbar__list {
289:   display: flex;
290:   align-items: center;
291:   gap: var(--space-2);
292: }
293: 
294: .navbar__link {
295:   display: block;
296:   padding: 0.5rem 0.85rem;
297:   border-radius: var(--radius-sm);
298:   color: var(--color-text-muted);
299:   font-weight: 600;
300:   font-size: var(--fs-sm);
301:   transition: color var(--transition), background-color var(--transition);
302: }
303: 
304: .navbar__link:hover,
305: .navbar__link.is-active {
306:   color: var(--color-accent);
307:   background-color: var(--color-accent-soft);
308: }
309: 
310: /* Theme toggle */
311: .theme-toggle {
312:   display: inline-flex;
313:   align-items: center;
314:   gap: var(--space-2);
315:   padding: 0.5rem 0.9rem;
316:   background-color: var(--color-surface);
317:   color: var(--color-text);
318:   border: 1px solid var(--color-border);
319:   border-radius: 999px;
320:   font: inherit;
321:   font-size: var(--fs-sm);
322:   font-weight: 600;
323:   cursor: pointer;
324:   transition: background-color var(--transition), border-color var(--transition),
325:     color var(--transition);
326: }
327: 
328: .theme-toggle:hover {
329:   border-color: var(--color-accent);
330:   color: var(--color-accent);
331: }
332: 
333: /* Hamburger — hidden on desktop */
334: .navbar__toggle {
335:   display: none;
336:   flex-direction: column;
337:   justify-content: center;
338:   gap: 5px;
339:   width: 2.75rem;
340:   height: 2.75rem;
341:   padding: 0.6rem;
342:   background-color: transparent;
343:   border: 1px solid var(--color-border);
344:   border-radius: var(--radius-sm);
345:   cursor: pointer;
346: }
347: 
348: .navbar__toggle-bar {
349:   display: block;
350:   width: 100%;
351:   height: 2px;
352:   background-color: var(--color-text);
353:   border-radius: 2px;
354:   transition: transform var(--transition), opacity var(--transition);
355: }
356: 
357: /* =========================================================
358:    Hero / About
359:    ========================================================= */
360: .site-main {
361:   padding-top: var(--navbar-height);
362: }
363: 
364: .hero__inner {
365:   max-width: 46rem;
366: }
367: 
368: .hero__eyebrow {
369:   margin-bottom: var(--space-3);
370:   color: var(--color-accent);
371:   font-weight: 600;
372:   font-size: var(--fs-md);
373: }
374: 
375: .hero__title {
376:   font-size: var(--fs-2xl);
377:   margin-bottom: var(--space-2);
378: }
379: 
380: .hero__subtitle {
381:   font-size: clamp(1.35rem, 3vw, 1.9rem);
382:   font-weight: 600;
383:   color: var(--color-text-muted);
384:   margin-bottom: var(--space-5);
385: }
386: 
387: .hero__bio {
388:   font-size: var(--fs-md);
389:   color: var(--color-text-muted);
390:   max-width: 40rem;
391:   margin-bottom: var(--space-6);
392: }
393: 
394: .hero__actions {
395:   display: flex;
396:   flex-wrap: wrap;
397:   gap: var(--space-3);
398:   margin-bottom: var(--space-7);
399: }
400: 
401: .hero__stats {
402:   display: grid;
403:   grid-template-columns: repeat(3, minmax(0, 1fr));
404:   gap: var(--space-4);
405:   margin: 0;
406: }
407: 
408: .stat {
409:   padding: var(--space-4);
410:   background-color: var(--color-surface);
411:   border: 1px solid var(--color-border);
412:   border-radius: var(--radius-md);
413:   box-shadow: var(--shadow-sm);
414: }
415: 
416: .stat__label {
417:   order: 2;
418:   font-size: var(--fs-sm);
419:   color: var(--color-text-muted);
420: }
421: 
422: .stat__value {
423:   order: 1;
424:   margin: 0 0 var(--space-1);
425:   font-size: var(--fs-xl);
426:   font-weight: 700;
427:   color: var(--color-accent);
428: }
429: 
430: .stat {
431:   display: flex;
432:   flex-direction: column;
433: }
434: 
435: /* =========================================================
436:    Skills
437:    ========================================================= */
438: .skills-grid {
439:   display: grid;
440:   grid-template-columns: repeat(auto-fit, minmax(16rem, 1fr));
441:   gap: var(--space-5);
442: }
443: 
444: .skill-card {
445:   display: flex;
446:   flex-direction: column;
447:   gap: var(--space-3);
448:   padding: var(--space-5);
449:   background-color: var(--color-surface);
450:   border: 1px solid var(--color-border);
451:   border-radius: var(--radius-md);
452:   box-shadow: var(--shadow-sm);
453:   transition: transform var(--transition), box-shadow var(--transition),
454:     border-color var(--transition);
455: }
456: 
457: .skill-card:hover {
458:   transform: translateY(-4px);
459:   box-shadow: var(--shadow-md);
460:   border-color: var(--color-accent);
461: }
462: 
463: .skill-card__icon {
464:   font-size: 1.75rem;
465:   line-height: 1;
466: }
467: 
468: .skill-card__title {
469:   font-size: var(--fs-lg);
470: }
471: 
472: .skill-card__text {
473:   color: var(--color-text-muted);
474:   font-size: var(--fs-sm);
475:   flex-grow: 1;
476: }
477: 
478: .skill-card__meter {
479:   height: 6px;
480:   background-color: var(--color-surface-alt);
481:   border: 1px solid var(--color-border);
482:   border-radius: 999px;
483:   overflow: hidden;
484: }
485: 
486: .skill-card__meter-fill {
487:   display: block;
488:   width: var(--level, 50%);
489:   height: 100%;
490:   background: linear-gradient(
491:     90deg,
492:     var(--color-accent),
493:     var(--color-accent-strong)
494:   );
495:   border-radius: inherit;
496: }
497: 
498: /* =========================================================
499:    Product — memory game
500:    ========================================================= */
501: .game {
502:   display: grid;
503:   gap: var(--space-5);
504:   max-width: 34rem;
505:   margin-inline: auto;
506: }
507: 
508: .game__stats {
509:   display: grid;
510:   grid-template-columns: repeat(3, minmax(0, 1fr));
511:   gap: var(--space-3);
512: }
513: 
514: .game__stat {
515:   display: flex;
516:   flex-direction: column;
517:   align-items: center;
518:   gap: var(--space-1);
519:   padding: var(--space-3);
520:   background-color: var(--color-surface);
521:   border: 1px solid var(--color-border);
522:   border-radius: var(--radius-md);
523:   box-shadow: var(--shadow-sm);
524: }
525: 
526: .game__stat-label {
527:   font-size: 0.75rem;
528:   font-weight: 700;
529:   letter-spacing: 0.1em;
530:   text-transform: uppercase;
531:   color: var(--color-text-muted);
532: }
533: 
534: .game__stat-value {
535:   font-size: var(--fs-lg);
536:   font-weight: 700;
537:   font-variant-numeric: tabular-nums;
538:   color: var(--color-accent);
539: }
540: 
541: /* --- Board --- */
542: .game__board {
543:   display: grid;
544:   grid-template-columns: repeat(4, minmax(0, 1fr));
545:   gap: var(--space-3);
546: }
547: 
548: /* --- Card --- */
549: .card {
550:   position: relative;
551:   aspect-ratio: 1;
552:   padding: 0;
553:   background: none;
554:   border: 0;
555:   border-radius: var(--radius-md);
556:   cursor: pointer;
557:   perspective: 700px;
558:   -webkit-tap-highlight-color: transparent;
559: }
560: 
561: .card:focus-visible {
562:   outline: 3px solid var(--color-focus);
563:   outline-offset: 3px;
564: }
565: 
566: .card__inner {
567:   position: absolute;
568:   inset: 0;
569:   transform-style: preserve-3d;
570:   transition: transform 380ms cubic-bezier(0.4, 0.2, 0.2, 1);
571: }
572: 
573: .card.is-flipped .card__inner,
574: .card.is-matched .card__inner {
575:   transform: rotateY(180deg);
576: }
577: 
578: .card__face {
579:   position: absolute;
580:   inset: 0;
581:   display: grid;
582:   place-items: center;
583:   overflow: hidden;
584:   backface-visibility: hidden;
585:   -webkit-backface-visibility: hidden;
586:   border-radius: var(--radius-md);
587:   border: 1px solid var(--color-border);
588: }
589: 
590: .card__face--back {
591:   background:
592:     repeating-linear-gradient(
593:       45deg,
594:       var(--color-accent-soft) 0 8px,
595:       transparent 8px 16px
596:     ),
597:     var(--color-surface);
598:   color: var(--color-accent);
599:   font-size: 1.35rem;
600:   font-weight: 800;
601:   letter-spacing: 0.05em;
602: }
603: 
604: .card__face--front {
605:   background-color: #0d0d0d;
606:   transform: rotateY(180deg);
607: }
608: 
609: .card__img {
610:   width: 100%;
611:   height: 100%;
612:   display: block;
613:   object-fit: cover;
614: }
615: 
616: /* --- Matched state --- */
617: .card.is-matched {
618:   cursor: default;
619: }
620: 
621: .card.is-matched .card__inner {
622:   transform: rotateY(180deg) scale(1);
623: }
624: 
625: .card.is-matched .card__face--front {
626:   border-color: var(--color-success);
627:   box-shadow: 0 0 0 2px var(--color-success);
628:   animation: card-pop 320ms ease;
629: }
630: 
631: .card.is-wrong .card__face--front {
632:   animation: card-shake 320ms ease;
633: }
634: 
635: @keyframes card-pop {
636:   0% { transform: rotateY(180deg) scale(1); }
637:   50% { transform: rotateY(180deg) scale(1.08); }
638:   100% { transform: rotateY(180deg) scale(1); }
639: }
640: 
641: @keyframes card-shake {
642:   0%, 100% { transform: rotateY(180deg) translateX(0); }
643:   25% { transform: rotateY(180deg) translateX(-4px); }
644:   75% { transform: rotateY(180deg) translateX(4px); }
645: }
646: 
647: /* --- Controls & status --- */
648: .game__controls {
649:   display: flex;
650:   flex-wrap: wrap;
651:   align-items: center;
652:   justify-content: center;
653:   gap: var(--space-4);
654:   text-align: center;
655: }
656: 
657: .game__status {
658:   flex: 1 1 100%;
659:   min-height: 1.5rem;
660:   margin: 0;
661:   font-size: var(--fs-sm);
662:   font-weight: 600;
663:   color: var(--color-text-muted);
664: }
665: 
666: .game__status.is-win {
667:   color: var(--color-success);
668: }
669: 
670: /* =========================================================
671:    Contact
672:    ========================================================= */
673: .contact__grid {
674:   display: grid;
675:   grid-template-columns: minmax(0, 1fr) minmax(0, 1.15fr);
676:   gap: var(--space-6);
677:   align-items: start;
678: }
679: 
680: .contact__channels {
681:   display: grid;
682:   gap: var(--space-4);
683: }
684: 
685: .contact-card {
686:   display: flex;
687:   align-items: center;
688:   gap: var(--space-4);
689:   padding: var(--space-4) var(--space-5);
690:   background-color: var(--color-surface);
691:   border: 1px solid var(--color-border);
692:   border-radius: var(--radius-md);
693:   box-shadow: var(--shadow-sm);
694: }
695: 
696: .contact-card__icon {
697:   font-size: 1.5rem;
698:   line-height: 1;
699: }
700: 
701: .contact-card__label {
702:   font-size: var(--fs-sm);
703:   font-weight: 600;
704:   color: var(--color-text-muted);
705:   margin-bottom: 2px;
706: }
707: 
708: .contact-card__value {
709:   font-weight: 600;
710:   word-break: break-word;
711: }
712: 
713: .contact-card__value--plain {
714:   color: var(--color-text);
715: }
716: 
717: /* Form */
718: .contact-form {
719:   display: grid;
720:   gap: var(--space-4);
721:   padding: var(--space-6);
722:   background-color: var(--color-surface);
723:   border: 1px solid var(--color-border);
724:   border-radius: var(--radius-lg);
725:   box-shadow: var(--shadow-md);
726: }
727: 
728: .contact-form__notice {
729:   padding: var(--space-3) var(--space-4);
730:   background-color: var(--color-accent-soft);
731:   border: 1px dashed var(--color-accent);
732:   border-radius: var(--radius-sm);
733:   font-size: var(--fs-sm);
734:   line-height: 1.6;
735: }
736: 
737: .contact-form__notice strong {
738:   color: var(--color-accent);
739: }
740: 
741: /* The inline email link sits inside a paragraph of text, so colour
742:    alone isn't enough to distinguish it — give it an underline too. */
743: .contact-form__notice a {
744:   font-weight: 600;
745:   text-decoration: underline;
746:   text-underline-offset: 2px;
747: }
748: 
749: .form-field {
750:   display: grid;
751:   gap: var(--space-2);
752: }
753: 
754: .form-field__label {
755:   font-size: var(--fs-sm);
756:   font-weight: 600;
757: }
758: 
759: .form-field__input {
760:   width: 100%;
761:   padding: 0.75rem 0.9rem;
762:   background-color: var(--color-bg);
763:   color: var(--color-text);
764:   border: 1px solid var(--color-border);
765:   border-radius: var(--radius-sm);
766:   font: inherit;
767:   font-size: var(--fs-base);
768:   transition: border-color var(--transition), box-shadow var(--transition);
769: }
770: 
771: .form-field__input::placeholder {
772:   color: var(--color-text-muted);
773: }
774: 
775: .form-field__input:focus {
776:   outline: none;
777:   border-color: var(--color-accent);
778:   box-shadow: 0 0 0 3px var(--color-accent-soft);
779: }
780: 
781: .form-field__input--area {
782:   resize: vertical;
783:   min-height: 8rem;
784: }
785: 
786: .form-status {
787:   min-height: 1.25rem;
788:   font-size: var(--fs-sm);
789:   font-weight: 600;
790:   color: var(--color-success);
791: }
792: 
793: .form-status.is-error {
794:   color: var(--color-error);
795: }
796: 
797: /* =========================================================
798:    Footer
799:    ========================================================= */
800: .site-footer {
801:   background-color: var(--color-primary);
802:   color: var(--color-primary-contrast);
803:   padding-block: var(--space-5);
804: }
805: 
806: .site-footer__inner {
807:   display: flex;
808:   flex-wrap: wrap;
809:   align-items: center;
810:   justify-content: space-between;
811:   gap: var(--space-3);
812: }
813: 
814: .site-footer__copy {
815:   font-size: var(--fs-sm);
816:   opacity: 0.85;
817: }
818: 
819: .site-footer__top {
820:   font-size: var(--fs-sm);
821:   font-weight: 600;
822:   color: var(--color-footer-accent);
823: }
824: 
825: /* =========================================================
826:    Responsive — Tablet & below
827:    ========================================================= */
828: @media (max-width: 900px) {
829:   .contact__grid {
830:     grid-template-columns: minmax(0, 1fr);
831:   }
832: }
833: 
834: @media (max-width: 768px) {
835:   .section {
836:     padding-block: var(--space-7);
837:   }
838: 
839:   .container {
840:     padding-inline: var(--space-4);
841:   }
842: 
843:   /* --- Mobile navigation --- */
844:   .navbar {
845:     flex-wrap: wrap;
846:     padding-inline: var(--space-4);
847:   }
848: 
849:   .navbar__toggle {
850:     display: flex;
851:     margin-left: auto;
852:   }
853: 
854:   .navbar__toggle[aria-expanded="true"] .navbar__toggle-bar:nth-child(1) {
855:     transform: translateY(7px) rotate(45deg);
856:   }
857: 
858:   .navbar__toggle[aria-expanded="true"] .navbar__toggle-bar:nth-child(2) {
859:     opacity: 0;
860:   }
861: 
862:   .navbar__toggle[aria-expanded="true"] .navbar__toggle-bar:nth-child(3) {
863:     transform: translateY(-7px) rotate(-45deg);
864:   }
865: 
866:   .navbar__menu {
867:     display: none;
868:     flex: 1 0 100%;
869:     flex-direction: column;
870:     align-items: stretch;
871:     gap: var(--space-3);
872:     padding-top: var(--space-3);
873:     padding-bottom: var(--space-2);
874:     border-top: 1px solid var(--color-border);
875:   }
876: 
877:   .navbar__menu.is-open {
878:     display: flex;
879:   }
880: 
881:   .navbar__list {
882:     flex-direction: column;
883:     align-items: stretch;
884:     gap: var(--space-1);
885:   }
