  cards.forEach(c => { for (let i = 0; i < 4; i++) c.click(); });
  const faceUpUnmatched = cards.filter(c => c.classList.contains('is-flipped') && !c.classList.contains('is-matched')).length;
  const bothClasses = cards.filter(c => c.classList.contains('is-flipped') && c.classList.contains('is-matched')).length;
  return { start,
    faceUpUnmatchedAfterStorm: faceUpUnmatched,
    flippedANDmatched: bothClasses,
    wrongFlags: cards.filter(c => c.classList.contains('is-wrong')).length,
    movesAfterStorm: document.getElementById('game-moves').textContent };
})()
`});

