(() => {
  const byGem = {};
  [...document.querySelectorAll('.card')].forEach((c, i) => {
    (byGem[c.dataset.gem] = byGem[c.dataset.gem] || []).push(i);
  });
  const list = [...document.querySelectorAll('.card')];
  Object.keys(byGem).forEach(g => {
    const pair = byGem[g];
    list[pair[0]].click();
    list[pair[1]].click();
  });
  const st = document.getElementById('game-status');
  return {
    pairsFound: Object.keys(byGem).length,
    winStatus: st.textContent,
    isWinClass: st.classList.contains('is-win'),
    moves: document.getElementById('game-moves').textContent,
    matches: document.getElementById('game-matches').textContent,
    time: document.getElementById('game-time').textContent,
    matchedCards: document.querySelectorAll('.card.is-matched').length,
    unmatchedFaceUp: [...document.querySelectorAll('.card')].filter(c => c.classList.contains('is-flipped') && !c.classList.contains('is-matched')).length
  };
})()
`});

return { E1: e1.value, timeAtWin: e1.value.time };

