const tabID = "tab_6ed1de8e-ddb4-4988-8475-ef8eceeb494f";
const e2 = await tools.browser.evaluate({ tabID, script: `
(() => {
  const res = {};

  // 1. win must freeze the timer (natural gap has passed since the win)
  res.timerFrozenAfterWin = document.getElementById('game-time').textContent === '00:00';
  res.timeNow = document.getElementById('game-time').textContent;

  // 2. restart x3 clears the win state completely
  const btn = document.getElementById('game-restart');
  for (let i = 0; i < 3; i++) btn.click();
  res.afterRestart = {
    moves: document.getElementById('game-moves').textContent,
    matches: document.getElementById('game-matches').textContent,
    time: document.getElementById('game-time').textContent,
    isWin: document.getElementById('game-status').classList.contains('is-win'),
    matched: document.querySelectorAll('.card.is-matched').length
  };

  // 3. fuzz: 500 ops — random card clicks with a forced restart every 40th
  let cs = [...document.querySelectorAll('.card')];
  for (let i = 0; i < 500; i++) {
    if (i % 40 === 0) {
      btn.click();
      cs = [...document.querySelectorAll('.card')];
    } else {
      cs[Math.floor(Math.random() * cs.length)].click();
    }
  }
  btn.click(); // normalize

  // 4. invariants on the final board
  const final = [...document.querySelectorAll('.card')];
  const gemCounts = {};
  final.forEach(c => { gemCounts[c.dataset.gem] = (gemCounts[c.dataset.gem] || 0) + 1; });
  res.invariants = {
    cardCount: final.length,
    everyGemExactlyTwice: Object.keys(gemCounts).length === 8 && Object.values(gemCounts).every(n => n === 2),
    moves: document.getElementById('game-moves').textContent,
    matches: document.getElementById('game-matches').textContent,
    time: document.getElementById('game-time').textContent,
    status: document.getElementById('game-status').textContent,
    isWin: document.getElementById('game-status').classList.contains('is-win'),
    matched: document.querySelectorAll('.card.is-matched').length,
    wrongFlags: document.querySelectorAll('.card.is-wrong').length,
    hOverflow: document.documentElement.scrollWidth > document.documentElement.clientWidth + 1
  };
  return res;
})()
`});

const msgs = await tools.browser.console({ tabID });
const issues = (msgs.messages || []).filter(m => m.level === "error" || m.level === "warning");
return { E2: e2.value, consoleIssues: issues.map(m => m.level + ": " + m.text) };

